function [bits, meta] = encodeSIB1UPER(msg)
%ENCODESIB1UPER Encode BCCH-DL-SCH/SIB1 with generated NR RRC UPER.
%
% This is no longer the historical private anchor bit layout. The encoder
% invokes the pinned pycrate-generated NR RRC codec; independent acceptance
% vectors are generated by asn1tools from official Release-18 ASN.1.

sixgr.rrc.asn1.validateSIB1ForScenario(msg, struct());
semantic = localSemantic(msg);
encoded = sixgr.rrc.asn1.invokeNRRRCCodec( ...
    "encode", struct("semantic", semantic));
bits = localHexToBits(string(encoded.uper_hex));
meta = struct( ...
    "Profile", string(encoded.profile), ...
    "ASN1Release", "3GPP TS 38.331 V18.9.0", ...
    "Codec", string(encoded.codec), ...
    "CodecVersion", string(encoded.codec_version), ...
    "ASN1SchemaSHA256", ...
        "29e55635561822bf625d9170f050552d65047c334a3c0a8a47797c8df1985db5", ...
    "PayloadBits", double(encoded.num_bits), ...
    "BodyBits", double(encoded.num_bits), ...
    "PayloadHash", string(encoded.sha256), ...
    "EncodedHex", string(encoded.uper_hex), ...
    "IndependentImplementation", ...
        "asn1tools-0.167.0 official-TS38331-i90", ...
    "SelfConsistencyOnly", false);
end

function semantic = localSemantic(msg)
sib1 = msg.message.c1.systemInformationBlockType1;
serv = sib1.servingCellConfigCommon;
dl = serv.downlinkConfigCommon;
ul = serv.uplinkConfigCommon;
plmn = sib1.cellAccessRelatedInfo.plmn_IdentityList(1);
prach = ul.initialUplinkBWP.rach_ConfigCommon;
schedule = sib1.si_SchedulingInfo.schedulingInfoList(1);
timers = sib1.ue_TimersAndConstants;
band = double(dl.frequencyInfoDL.frequencyBandList(1).freqBandIndicatorNR);
semantic = struct( ...
    "mcc", char(string(plmn.mcc)), ...
    "mnc", char(string(plmn.mnc)), ...
    "tracking_area_code", double( ...
        sib1.cellAccessRelatedInfo.trackingAreaCode), ...
    "cell_identity", double( ...
        sib1.cellAccessRelatedInfo.cellIdentity), ...
    "cell_reserved", char(string( ...
        sib1.cellAccessRelatedInfo.cellReservedForOperatorUse)), ...
    "q_rx_lev_min", double(sib1.cellSelectionInfo.q_RxLevMin), ...
    "q_qual_min", double(sib1.cellSelectionInfo.q_QualMin), ...
    "band", band, ...
    "offset_to_point_a", double( ...
        dl.frequencyInfoDL.offsetToPointA), ...
    "subcarrier_spacing_khz", localSCSValue( ...
        dl.frequencyInfoDL.scs_SpecificCarrierList.subcarrierSpacing), ...
    "carrier_bandwidth_rb", double( ...
        dl.frequencyInfoDL.scs_SpecificCarrierList.carrierBandwidth), ...
    "absolute_frequency_point_a", double( ...
        ul.frequencyInfoUL.absoluteFrequencyPointA), ...
    "prach_configuration_index", double(prach.configurationIndex), ...
    "preamble_format", char(string(prach.preambleFormat)), ...
    "msg1_fdm", char(string(prach.msg1FDM)), ...
    "msg1_frequency_start", double(prach.msg1FrequencyStart), ...
    "zero_correlation_zone", double( ...
        prach.zeroCorrelationZoneConfig), ...
    "preamble_received_target_power_dbm", double( ...
        prach.preambleReceivedTargetPower_dBm), ...
    "preamble_trans_max", char(string(prach.preambleTransMax)), ...
    "power_ramping_step", char(string(prach.powerRampingStep)), ...
    "ra_response_window", char(string(prach.raResponseWindow)), ...
    "ssb_per_rach_choice", char(string(prach.ssbPerRACHChoice)), ...
    "cb_preambles_per_ssb", char(string(prach.cbPreamblesPerSSB)), ...
    "contention_resolution_timer", char(string( ...
        prach.contentionResolutionTimer)), ...
    "root_sequence_index", double(prach.rootSequenceIndex), ...
    "msg1_subcarrier_spacing_khz", double( ...
        prach.msg1SubcarrierSpacing_kHz), ...
    "restricted_set_config", char(localRestrictedSet( ...
        prach.restrictedSet)), ...
    "num_preambles", double(prach.nPreambles), ...
    "si_broadcast_status", char(string( ...
        schedule.si_BroadcastStatus)), ...
    "si_periodicity", char(string(schedule.si_Periodicity)), ...
    "mapped_sib_type", char(string(schedule.mappedSIBType)), ...
    "si_window_length", char(string( ...
        sib1.si_SchedulingInfo.si_WindowLength)), ...
    "modification_period_coeff", char(string( ...
        dl.bcch_Config.modificationPeriodCoeff)), ...
    "default_paging_cycle", char(string( ...
        dl.pcch_Config.defaultPagingCycle)), ...
    "paging_frame_choice", char(string( ...
        dl.pcch_Config.nAndPagingFrameOffset.choice)), ...
    "paging_frame_offset", double( ...
        dl.pcch_Config.nAndPagingFrameOffset.offset), ...
    "paging_ns", char(string(dl.pcch_Config.ns)), ...
    "time_alignment_timer", char(string( ...
        ul.timeAlignmentTimerCommon)), ...
    "ssb_positions_in_burst", char(string( ...
        serv.ssb_PositionsInBurst.inOneGroup)), ...
    "ssb_periodicity", char(string( ...
        serv.ssb_periodicityServingCell)), ...
    "ss_pbch_block_power_dbm", double(serv.ss_PBCH_BlockPower), ...
    "t300", char(string(timers.t300)), ...
    "t301", char(string(timers.t301)), ...
    "t310", char(string(timers.t310)), ...
    "n310", char(string(timers.n310)), ...
    "t311", char(string(timers.t311)), ...
    "n311", char(string(timers.n311)), ...
    "t319", char(string(timers.t319)));
end

function value = localSCSValue(name)
value = str2double(erase(string(name), "kHz"));
if ~isfinite(value)
    error("sixgr:rrc:asn1:UnsupportedSIB1IE", ...
        "Invalid SIB1 subcarrier spacing enum '%s'.", string(name));
end
end

function value = localRestrictedSet(name)
name = lower(strtrim(string(name)));
if any(name == ["unrestrictedset","unrestricted","false","0"])
    value = "unrestrictedSet";
elseif any(name == ["restrictedsettypea","typea","restricteda"])
    value = "restrictedSetTypeA";
elseif any(name == ["restrictedsettypeb","typeb","restrictedb"])
    value = "restrictedSetTypeB";
else
    error("sixgr:rrc:asn1:UnsupportedSIB1IE", ...
        "Unsupported PRACH restricted-set value '%s'.", name);
end
end

function bits = localHexToBits(hex)
text = char(upper(erase(string(hex), " ")));
if mod(numel(text), 2) ~= 0 || ...
        any(~ismember(text, ['0':'9','A':'F']))
    error("sixgr:rrc:asn1:CodecOutputInvalid", ...
        "NR RRC codec returned invalid hexadecimal UPER.");
end
bytes = uint8(sscanf(text, "%2x"));
bits = zeros(numel(bytes) * 8, 1, "int8");
for ii = 1:numel(bytes)
    for jj = 1:8
        bits((ii - 1) * 8 + jj) = int8( ...
            bitget(bytes(ii), 9 - jj));
    end
end
end
